function useStoredState(key, fallback) {
  const { getWorkspaceValue, setWorkspaceValue, isReady, isAuthenticated } = useAuth();
  const [value, setValue] = useState(fallback);
  const [hydrated, setHydrated] = useState(false);

  useEffect(() => {
    let active = true;
    if (!isReady || !isAuthenticated) return undefined;
    setHydrated(false);
    getWorkspaceValue(key).then((saved) => {
      if (!active) return;
      if (saved !== null && saved !== undefined) setValue(saved);
      setHydrated(true);
    }).catch((error) => {
      console.error(`Could not load workspace state: ${key}`, error);
      if (active) setHydrated(true);
    });
    return () => { active = false; };
  }, [getWorkspaceValue, isAuthenticated, isReady, key]);

  useEffect(() => {
    if (!hydrated || !isAuthenticated) return;
    const timer = window.setTimeout(() => {
      setWorkspaceValue(key, value).catch((error) => console.error(`Could not persist workspace state: ${key}`, error));
    }, 150);
    return () => window.clearTimeout(timer);
  }, [hydrated, isAuthenticated, key, setWorkspaceValue, value]);

  return [value, setValue];
}

export function useDemoToasts() {
  const [toasts, setToasts] = useState([]);
  const showToast = (message, type = 'success') => {
    const id = Date.now() + Math.random();
    setToasts((items) => [...items, { id, message, type }]);
    window.setTimeout(() => setToasts((items) => items.filter((item) => item.id !== id)), 3600);
  };
  const Toasts = () => <div className="fixed bottom-5 right-5 z-[80] flex w-[min(360px,calc(100vw-2.5rem))] flex-col gap-2" aria-live="polite">
    {toasts.map((toast) => <div key={toast.id} className={`animate-slide-up flex items-start gap-3 rounded-2xl border p-4 shadow-xl backdrop-blur ${toast.type === 'error' ? 'border-rose-200 bg-rose-50 text-rose-950 dark:border-rose-900/70 dark:bg-rose-950 dark:text-rose-100' : 'border-emerald-200 bg-white/95 text-slate-900 dark:border-emerald-900 dark:bg-slate-900/95 dark:text-white'}`}>
      {toast.type === 'error' ? <CircleAlert className="mt-0.5 h-5 w-5 shrink-0 text-rose-500" /> : <CheckCircle2 className="mt-0.5 h-5 w-5 shrink-0 text-emerald-500" />}
      <span className="flex-1 text-sm font-medium">{toast.message}</span>
      <button aria-label="Dismiss notification" onClick={() => setToasts((items) => items.filter((item) => item.id !== toast.id))}><X className="h-4 w-4 opacity-60" /></button>
    </div>)}
  </div>;
  return { showToast, Toasts };
}

export function Modal({ open, onClose, title, children, size = 'md', labelledBy = 'dialog-title' }) {
  useEffect(() => {
    if (!open) return undefined;
    const onKey = (event) => event.key === 'Escape' && onClose?.();
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [open, onClose]);
  if (!open) return null;
  const widths = { sm: 'max-w-md', md: 'max-w-xl', lg: 'max-w-3xl', xl: 'max-w-5xl' };
  return <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 sm:p-6" role="presentation">
    <button id="modal-backdrop" aria-label="Close dialog" className="absolute inset-0 cursor-default bg-slate-950/45 backdrop-blur-sm" onClick={onClose} />
    <section role="dialog" aria-modal="true" aria-labelledby={labelledBy} className={`animate-scale-in relative max-h-[min(90vh,780px)] w-full ${widths[size]} overflow-auto rounded-3xl border border-white/40 bg-white shadow-2xl dark:border-slate-700 dark:bg-slate-900`}>
      <div className="sticky top-0 z-10 flex items-center justify-between border-b border-slate-100 bg-white/95 px-5 py-4 backdrop-blur dark:border-slate-800 dark:bg-slate-900/95 sm:px-6">
        <h2 id={labelledBy} className="text-lg font-semibold text-slate-950 dark:text-white">{title}</h2>
        <button id="close-modal-button" onClick={onClose} className="rounded-xl p-2 text-slate-500 transition hover:bg-slate-100 hover:text-slate-950 dark:hover:bg-slate-800 dark:hover:text-white" aria-label="Close modal"><X className="h-5 w-5" /></button>
      </div>
      {children}
    </section>
  </div>;
}

export function ConfirmDialog({ open, onClose, onConfirm, title = 'Are you sure?', description, confirmLabel = 'Confirm', danger = false }) {
  return <Modal open={open} onClose={onClose} title={title} size="sm">
    <div className="p-6">
      <div className={`mb-5 grid h-11 w-11 place-items-center rounded-2xl ${danger ? 'bg-rose-100 text-rose-600 dark:bg-rose-500/15' : 'bg-violet-100 text-violet-600 dark:bg-violet-500/15'}`}><CircleAlert className="h-5 w-5" /></div>
      <p className="text-sm leading-6 text-slate-600 dark:text-slate-300">{description}</p>
      <div className="mt-7 flex flex-col-reverse gap-2 sm:flex-row sm:justify-end">
        <Button variant="secondary" onClick={onClose}>Cancel</Button>
        <Button id="confirm-dialog-action" variant={danger ? 'danger' : 'primary'} onClick={() => { onConfirm?.(); onClose?.(); }}>{confirmLabel}</Button>
      </div>
    </div>
  </Modal>;
}

export function Button({ children, className = '', variant = 'primary', size = 'md', loading = false, ...props }) {
  const variants = {
    primary: 'bg-violet-600 text-white shadow-sm shadow-violet-600/25 hover:bg-violet-700 focus-visible:ring-violet-500',
    secondary: 'border border-slate-200 bg-white text-slate-700 hover:border-slate-300 hover:bg-slate-50 focus-visible:ring-slate-300 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-200 dark:hover:bg-slate-800',
    ghost: 'text-slate-600 hover:bg-slate-100 hover:text-slate-950 focus-visible:ring-slate-300 dark:text-slate-300 dark:hover:bg-slate-800 dark:hover:text-white',
    danger: 'bg-rose-600 text-white shadow-sm shadow-rose-600/25 hover:bg-rose-700 focus-visible:ring-rose-500',
    soft: 'bg-violet-50 text-violet-700 hover:bg-violet-100 focus-visible:ring-violet-300 dark:bg-violet-500/15 dark:text-violet-300 dark:hover:bg-violet-500/25',
  };
  const sizes = { sm: 'min-h-8 px-3 text-xs', md: 'min-h-10 px-4 text-sm', lg: 'min-h-12 px-5 text-sm' };
  return <button disabled={loading || props.disabled} className={`inline-flex items-center justify-center gap-2 rounded-xl font-medium transition duration-200 focus:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-60 dark:focus-visible:ring-offset-slate-950 ${variants[variant]} ${sizes[size]} ${className}`} {...props}>
    {loading && <RefreshCw className="h-4 w-4 animate-spin" />}{children}
  </button>;
}

