function SectionTitle({ eyebrow, title, description, action }) { return <div className="mb-5 flex flex-wrap items-end justify-between gap-3"><div>{eyebrow && <p className="mb-1 text-xs font-semibold uppercase tracking-[.16em] text-violet-600 dark:text-violet-400">{eyebrow}</p>}<h2 className="text-lg font-semibold tracking-tight text-slate-950 dark:text-white">{title}</h2>{description && <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">{description}</p>}</div>{action}</div>; }
function Badge({ children, color = 'slate' }) { const colors = { slate: 'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-300', violet: 'bg-violet-50 text-violet-700 dark:bg-violet-500/15 dark:text-violet-300', emerald: 'bg-emerald-50 text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-300', rose: 'bg-rose-50 text-rose-700 dark:bg-rose-500/15 dark:text-rose-300', amber: 'bg-amber-50 text-amber-700 dark:bg-amber-500/15 dark:text-amber-300', sky: 'bg-sky-50 text-sky-700 dark:bg-sky-500/15 dark:text-sky-300' }; return <span className={`inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-xs font-medium ${colors[color]}`}>{children}</span>; }
function Avatar({ src, name, size = 'md', className = '' }) { const sizes = { xs: 'h-6 w-6 text-[9px]', sm: 'h-8 w-8 text-[10px]', md: 'h-10 w-10 text-xs', lg: 'h-16 w-16 text-lg' }; return src ? <img src={src} alt="" className={`${sizes[size]} rounded-full border-2 border-white object-cover dark:border-slate-800 ${className}`} /> : <span className={`${sizes[size]} inline-grid place-items-center rounded-full bg-violet-100 font-semibold text-violet-700 dark:bg-violet-500/20 dark:text-violet-200 ${className}`}>{name?.split(' ').map((part) => part[0]).slice(0, 2).join('')}</span>; }
function Field({ label, hint, error, children, required, id }) { return <div className="space-y-1.5"><label htmlFor={id} className="text-sm font-medium text-slate-700 dark:text-slate-200">{label}{required && <span className="ml-0.5 text-rose-500">*</span>}</label>{children}{error ? <p className="flex items-center gap-1 text-xs text-rose-600"><CircleAlert className="h-3.5 w-3.5" />{error}</p> : hint && <p className="text-xs text-slate-500">{hint}</p>}</div>; }
const inputClass = 'w-full rounded-xl border border-slate-200 bg-white px-3.5 py-2.5 text-sm text-slate-900 outline-none transition placeholder:text-slate-400 focus:border-violet-500 focus:ring-4 focus:ring-violet-500/10 disabled:bg-slate-50 dark:border-slate-700 dark:bg-slate-950 dark:text-white dark:placeholder:text-slate-600 dark:disabled:bg-slate-900';
