function Progress({ value, color = 'violet', className = '' }) { const colors = { violet: 'bg-violet-600', sky: 'bg-sky-500', emerald: 'bg-emerald-500', amber: 'bg-amber-500', rose: 'bg-rose-500' }; return <div className={`h-2 overflow-hidden rounded-full bg-slate-100 dark:bg-slate-800 ${className}`}><div className={`h-full rounded-full transition-all duration-700 ${colors[color]}`} style={{ width: `${value}%` }} /></div>; }
